const crypto = require('crypto');
const item = items[0].json;
const raw = typeof item.body === 'string' ? item.body : JSON.stringify(item.body);
const timestamp = item.headers['x-proofcore-timestamp'];
const age = Math.abs(Date.now() / 1000 - Number(timestamp));
if (!Number.isFinite(age) || age > 300) throw new Error('stale webhook timestamp');
const secret = process.env.PROOFCORE_WEBHOOK_SECRET || '';
const expected = `sha256=${crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest('hex')}`;
const supplied = item.headers['x-proofcore-signature'] || '';
if (expected.length !== supplied.length || !crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(supplied))) throw new Error('invalid webhook signature');
const event = JSON.parse(raw);
if (event.event !== 'payment.webhook.processed') throw new Error('unsupported event');
return [{ json: { verified: true, receivedAt: new Date().toISOString(), event } }];

const event = items[0].json.event;
const slackUrl = process.env.SLACK_WEBHOOK_URL || '';
let notification = 'skipped';
if (slackUrl) {
  const text = [`✅ PROOFCORE payment verified`, `Provider: ${event.provider}`, `Result: ${event.result || 'verified'}`, `Intent: ${event.intentId || 'n/a'}`, `Provider event: ${event.providerEventId || 'n/a'}`, `Occurred: ${event.occurredAt}`].join('\n');
  const response = await fetch(slackUrl, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ text }) });
  notification = response.ok ? 'sent' : `failed:${response.status}`;
}
return [{ json: { ...items[0].json, notification } }];
